  for (y = 0; y < height; y += 4) {
    for (x = 0; x < width; x += 4) {
      for (row = 0; row < 4; row++) {
        if ((y + row) >= height)
          continue;
        line = (y + row) * width;
        for (x = 0; x < 4; x++) {
          if ((x + x) >= width)
