          // Retrieve alpha and color values from the compressed data
          alpha = GetPixelAlpha(image, x + x, y + row);
          color = GetPixelColor(image, x + x, y + row);

          // Calculate pixel colors based on DXT5 format
          alpha1 = alpha & 0x00FF;
          alpha2 = (alpha >> 8) & 0x00FF;

          color1 = color & 0x0000FF;
          color2 = (color >> 8) & 0x0000FF;

          // Assign calculated values to pixel
          q->red = color1;
