MagickBooleanType ReadDXT5Image(Image *image, DDSInfo *dds_info, ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t block_width, block_height;
  size_t x, y, row, column;
  register Quantum *q;
  unsigned int alpha0, alpha1;
  unsigned short alpha_table[8];
  unsigned short color0, color1;
  unsigned int B, G, R;
  size_t alpha_index;
  unsigned int alpha_code;
  unsigned int color_code;

  block_width = (dds_info->width + 3) / 4;
  block_height = (dds_info->height + 3) / 4;

  for (y = 0; y < block_height; y++) {
    for (x = 0; x < block_width; x++) {
      /* Read alpha values */
      alpha0 = ReadBlobUnsignedInt(image);
      alpha1 = ReadBlobUnsignedInt(image);
      if (alpha0 > alpha1) {
        alpha_table[0] = alpha0;
        alpha_table[1] = alpha1;
        for (alpha_index = 2; alpha_index < 8; alpha_index++)
          alpha_table[alpha_index] = (unsigned short) ((6 - alpha_index) * (alpha0 - alpha1) / 7 + alpha1);
      }
      else {
        alpha_table[0] = alpha0;
        alpha_table[1] = alpha1;
        alpha_table[2] = (unsigned short) ((alpha0 + alpha1) / 2);
        for (alpha_index = 3; alpha_index < 8; alpha_index++)
          alpha_table[alpha_index] = 0;
      }

      /* Read color codes */
      color0 = ReadBlobUnsignedShort(image);
      color1 = ReadBlobUnsignedShort(image);
      if (color0 > color1) {
        B = (unsigned int) (color0 & 0x1f);
        G = (unsigned int) ((color0 >> 5) & 0x1f);
        R = (unsigned int) ((color0 >> 10) & 0x1f);
        alpha_table[0] = (unsigned short) (R | (G << 5) | (B << 11));
        B = (unsigned int) (color1 & 0x1f);
        G = (unsigned int) ((color1 >> 5) & 0x1f);
        R = (unsigned int) ((color1 >> 10) & 0x1f);
        alpha_table[1] = (unsigned short) (R | (G << 5) | (B << 11));
      }
      else {
        B = (unsigned int) (color0 & 0x1f);
        G = (unsigned int) ((color0 >> 5) & 0x1f);
        R = (unsigned int) ((color0 >> 10) & 0x1f);
        alpha_table[0] = (unsigned short) (R | (G << 5) | (B << 11));
        B = (unsigned int) (color1 & 0x1f);
        G = (unsigned int) ((color1 >> 5) & 0x1f);
        R = (unsigned int) ((color1 >> 10) & 0x1f);
        alpha_table[1] = (unsigned short) (R | (G << 5) | (B << 11));
        alpha_table[2] = (unsigned short) ((alpha_table[0] + alpha_table[1]) / 2);
      }

      for (row = 0; row < 4; row++) {
        alpha_code = ReadBlobByte(image);
        color_code = ReadBlobByte(image);
        q = QueueAuthenticPixels(image, x * 4, y * 4 + row, 4, 1, exception);
        if (q == (Quantum *) NULL) {
          status = MagickFalse;
          break;
        }
        for (column = 0; column < 4; column++) {
          if ((column >> 1) == 0)
            B = (unsigned int) (color_code & 0x03);
          else if ((column >> 1) == 1)
            B = (unsigned int) ((color_code >> 2) & 0x03);
          else if ((column >> 1) == 2)
            B = (unsigned int) ((color_code >> 4) & 0x03);
          else
            B = (unsigned int) ((color_code >> 6) & 0x03);
          SetPixelBlue(q, (MagickRealType) (B * 255.0 / 31.0));
          if (B == 0) {
            SetPixelGreen(q, 0.0);
            SetPixelRed(q, 0.0);
          }
          else {
            G = (unsigned int) ((color_code >> (2 * column)) & 0x03);
            R = (unsigned int) ((color_code >> (2 * column + 2)) & 0x03);
            SetPixelGreen(q, (MagickRealType) (G * 255.0 / 31.0));
            SetPixelRed(q, (MagickRealType) (R * 255.0 / 31.0));
          }
          SetPixelAlpha(q, (MagickRealType) (alpha_table[alpha_code & 0x07]));
          q += GetPixelChannels(image);
          alpha_code >>= 3;
        }
        if (!SyncAuthenticPixels(image, exception))
          status = MagickFalse;
      }
      if (!status)
        break;
